    for cells in objs:
        d=0
        while True:
            nd=d+1
            ok=True
            for r,c in cells:
                nr = r-nd if top else r+nd
                if nr<0 or nr>=h or g[nr][c]==2 or out[nr][c]!=0:
                    ok=False; break
            if ok: d=nd
            else: break
        for r,c in cells:
            nr = r-d if top else r+d
            out[nr][c]=g[r][c]
    return out

