def components(grid):
    """The 4-connected nonzero objects as lists of (row, col) cells."""
    h, w = len(grid), len(grid[0]); seen = [[False]*w for _ in range(h)]; objs = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc] and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                objs.append(cells)
    return objs

def gravity(grid, bar=2):
    """Every object slides toward the full row of color bar (top if it is row 0, else bottom), stacking on the bar and settled objects."""
    h, w = len(grid), len(grid[0])
    top = any(v == bar for v in grid[0])
    out = [row[:] for row in grid]
    for row in out:
        for j in range(w):
            if row[j] not in (0, bar): row[j] = 0
    objs = components(grid)
    objs.sort(key=lambda cs: (min(r for r, c in cs) if top else max(r for r, c in cs)), reverse=not top)
    for cells in objs:
        d = 0
        while all(0 <= (r-d if top else r+d) < h and grid[r-d if top else r+d][c] != bar and out[r-d if top else r+d][c] == 0 for r, c in cells):
            d += 1
        for r, c in cells:
            out[r-d if top else r+d][c] = grid[r][c]
    return out
